export const selectInstantResultsState = (state: GlobalState): string =>
  state.search.instantResults.state;

export const selectInstantResults = (state: GlobalState): SearchResponse => {
  if (selectInstantResultsState(state) !== 'FULFILLED') return null;
  const { instantResults } = state.search;

  return instantResults.data;
};

const selectEntities = (state: GlobalState) => state.search.$entities;

const selectProviderQuery = (state: GlobalState): string =>
  state.search.provided;

