import { GlobalState } from '../../../types.global';
import { selectFeatureFlags, selectIsUserRegular } from '../../../store/selectors';
import { timeInMs } from '../../../../shared';
import { VeveBanner } from './types';

export const createSelectShouldFetch = (now: number) => (state: GlobalState): boolean => {
  if (!selectIsUserRegular(state)) return false;
  if (state.banner.disabledUntil) return false;

  const { BANNER_ON } = selectFeatureFlags(state);
  if (!BANNER_ON) return false;

  const { savedAt } = state.banner;
  return !savedAt || savedAt < now - timeInMs.minute;
}

