export const selectBanner = (state: GlobalState): VeveBanner | null => {
  const { BANNER_ON } = selectFeatureFlags(state);
  if (!BANNER_ON) return null;

  if (!selectIsUserRegular(state)) return null;
  if (state.banner.disabledUntil) return null;

  return state.banner?.list?.[0];
}
