// Don't shorten it. Pull only what is needed so bg script is lighter
import { selectAdTiles } from '../../newtab/features/tiles/slice/selectors';
import { selectCommand, selectEngine } from '../../newtab/features/searchForm/slice/selectors';
import { GlobalState } from '../../newtab/types.global';
import { getStorageItems } from '../chromeApi';
import { ContentAds } from '../../content/annotations/interfaces';

interface BgPicUserProps {
  Category_of_background_active: string,
  Rotation_of_background_images_active: string
}

const getBgPicUserProperties = (state): BgPicUserProps => {
  const { gallery, mode } = state.ui;
  if (mode === 'gallery') {
    return {
      Category_of_background_active: gallery.category,
      Rotation_of_background_images_active: gallery.rotation.type
        ? `${gallery.rotation.type}:${gallery.rotation.value}`
        : 'fixed',
    };
  }

  if (mode === 'custom') {
    return {
      Category_of_background_active: 'custom',
      Rotation_of_background_images_active: 'fixed',
    };
  }

  return {
    Category_of_background_active: mode,
    Rotation_of_background_images_active: 'fixed',
  };
};

interface Props extends BgPicUserProps {
  User_entered_name: boolean;
  User_has_friends: number;
  User_bottles_collected: number;
  Extension_installed: string;
  Ad_tiles_visible: number;
  NTP_trivia_displayed_counter: number;
  Extension_variant: string;
  Search_engine: string;
  Default_seach_bar: string;
}

export const getAmplitudeUserProperties = async (state: GlobalState): Promise<Props> => {
  if (!state?.user) return null;

  const storage = await getStorageItems<{contentAds: ContentAds}>(['contentAds']);

  const friendsList = state.friends.friends.list || [];

  const result = {
    ...getBgPicUserProperties(state),

    Annotations_hidden: !!storage?.contentAds?.isButtonHidden,
    User_entered_name: !!state.user.loggedUser.value,
    User_has_friends: friendsList.length,
    User_bottles_collected: Math.floor(state.user.shells.shellsCounter / 100),
    Extension_installed: 'CHROME',
    Ad_tiles_visible: selectAdTiles(state).length,
    NTP_trivia_displayed_counter: state.trivia.visibility.totalCount,
    Extension_variant: [
      process.env.APP_TYPE === 'lite' ? 'NTP' : 'Search',
      process.env.APP_PLATFORM === 'web' ? '_web' : '',
    ].join(''),
    Search_engine: selectEngine(state),
    Default_seach_bar: state.search.isAutofocus
      ? 'NTP search box'
      : 'omnibox',
    Shortcut: selectCommand(state)?.shortcut,
    Google_Accounts: state.user.googleAccounts?.length || 0,
  };

  return Object.keys(result).reduce((acc, key) => {
    const value = result[key];
    return (typeof value === 'undefined' || value === null) ? acc : { ...acc, [key]: value };
  }, {}) as Props;
};
