export const fetchMessages = (shouldRefresh = false): Thunk => async (dispatch, getState) => {
  const { STORY_MESSAGES } = selectFeatureFlags(getState());

  try {
    // 'https://assets.oceanhero.today/extension/extension-story/messages-backup.json',
    // const filename = STORY_MESSAGES || `messages${
    //   process.env.APP_TYPE === 'lite' ? '-ntp' : ''
    // }.json`;

    // const filename = STORY_MESSAGES || `messages-backup.json`;
    const filename = STORY_MESSAGES;

    if (!filename) return null;

    const storyJSON = await cachedFetch<StoryResponse>(
      `https://oceanhero.today/extension/story/${filename}`,
      timeInMs.hour
    );

    const state = getState();
    if (shouldRefresh) {
      const story = processMessages(storyJSON, {
        ...state,
        story: {
          ...initialStoryState,
          shownMessagesIds: state.story.shownMessagesIds,
        }
      });

      const newState = getInitialStoryState({
        ...state,
        story: { ...initialStoryState, ...story }
      });
      console.log(newState);

      dispatch(storySlice.actions.fetchMessagesFulfilled(newState));
    } else {
      const result = processMessages(storyJSON, getState());
      dispatch(storySlice.actions.fetchMessagesFulfilled(result));
    }
  } catch (err) {
    console.error('fetchMessages', err);
    return null;
  }
};

export default storySlice.reducer;

