export const fetchSuggestions =
  ({ term, inputType }: { term: string; inputType: string }): Thunk =>
  async (dispatch, getState) => {
    const state = getState();

    const engine = selectEngine(state);
    const isRegular = selectIsUserRegular(state);
    const {
      AD_AUTOSUGGESTION,
      SEARCH_BOX_INSTANT_ANSWERS,
      THINKSUGGEST_ADS,
      ADMARKETPLACE_FEED,
    } = selectFeatureFlags(state);
    const choosenSearchTag = selectChoosenSearchTag(state);

    const isAds = !!(() => {
      if (choosenSearchTag) return false;
      // if (engine === 'google' || choosenSearchTag) return false;
      return isRegular ? AD_AUTOSUGGESTION || THINKSUGGEST_ADS : null;
    })();

    if (!term) return null;

    const searchTerm = choosenSearchTag
      ? `${choosenSearchTag.s} ${term}`
      : term;

    const list = await (() => {
      const isAdMarketplaceAds = isAds && !THINKSUGGEST_ADS;

      if (
        isAdMarketplaceAds &&
        ADMARKETPLACE_FEED &&
        searchTerm.length >= Number(ADMARKETPLACE_FEED)
      ) {
        return Promise.all([
          requestAdmarketplaceLongTailSuggestions(term),
          requestOrganicSuggestions(searchTerm, engine, choosenSearchTag),
        ]).then(createFormatAdMarketplaceLongtail(searchTerm, engine));
      }

      return isAdMarketplaceAds
        ? requestAdSuggestions(searchTerm).then(
            createFormatAdMarketplace(searchTerm, engine)
          )
        : requestOrganicSuggestions(searchTerm, engine, choosenSearchTag).then(
            async (result): Promise<Suggestion[]> => {
              if (isAds && THINKSUGGEST_ADS) {
                try {
                  const simpleList = result.map((el) => el.term || el);
                  const thinksuggestList = await fetchThinksuggest(
                    searchTerm,
                    engine,
                    simpleList
                  );

                  console.log('thinksuggestList', thinksuggestList);

                  if (thinksuggestList?.length) {
                    return thinksuggestList;
                  }
                } catch (err) {
                  console.error('fetchSuggestions:thinksuggest', err);
                }
              }

              return createFormatOrganic(searchTerm, engine)(result);
            }
          );
    })();

    dispatch(
      fetchedSuggestions({
        term: searchTerm,
        inputType,
        list,
      })
    );

    const newState = getState();
    const renderedList = selectSuggestions(newState);
    const highlighted = selectHighlighted(newState);

    if (!highlighted && renderedList.length) {
      const [first] = renderedList;
      if (
        (['ad', 'url', 'website'].includes(first.type) ||
          // This is the case for thinksuggest
          (['organic'].includes(first.type) && first.provider)) &&
        inputType !== 'deleteContentBackward' &&
        checkPreselectMatch(first, term)
      ) {
        dispatch(
          actions.suggestionNavigate({ id: first.id, inputType: 'preselected' })
        );
      }
    } else if (
      highlighted &&
      newState.search.highlighted.inputType === 'preselected' &&
      renderedList.indexOf(highlighted) !== 0
    ) {
      dispatch(actions.suggestionNavigate({ id: null, inputType: null }));
    }

    const termForInstant = (() => {
      const organic = renderedList.find(({ type }) =>
        ['organic', 'searchTag', 'historyOrganic'].includes(type)
      );
      return organic?.term || term;
    })();

    if (
      SEARCH_BOX_INSTANT_ANSWERS &&
      !THINKSUGGEST_ADS &&
      inputType !== 'preselected' &&
      termForInstant &&
      termForInstant !==
        newState.search.instantResults.data?.queryContext.originalQuery
    ) {
      dispatch(fetchInstantResults(termForInstant));
    }
  };

export const fetchEntities = createAsyncThunk(
  'searchForm/fetchEntities',
  async () => {
    const [{ default: searchTags }, zp] = await Promise.all([
      import('../data/searchTags.json'),
      requestZeropark(),
    ]);

    return { searchTags, zp };
  }
);

export const updatedInput =
  (term: string, inputType: string): Thunk =>
  async (dispatch, getState) => {
    const state = getState();
    const engine = selectEngine(state);

    if (!engine) return;

    dispatch(actions.userTyping({ term, inputType }));
    if (term) dispatch(fetchSuggestions({ term, inputType }));
  };

export const toggledFocus =
  (isFocus: boolean): Thunk =>
  async (dispatch, getState) => {
    const state = getState();

    const { SEARCH_BOX_FOCUS_HISTORY } = selectFeatureFlags(state);
    const engine = selectEngine(state);
    dispatch(
      engine
        ? actions.toggledInputFocus(isFocus)
        : actions.toggledChooseEngine(true)
    );

    if (
      engine &&
      !selectSuggestions(state).length &&
      isFocus &&
      (SEARCH_BOX_FOCUS_HISTORY || state.search.provided)
    ) {
      dispatch(updatedInput(state.search.provided, 'focus'));
    }
  };

export const changedInput =
  (evt?: ChangeEvent): Thunk =>
  async (dispatch, getState) => {
    const state = getState();

    const { value } = evt.currentTarget;

    const engine = selectEngine(state);
    if (!engine) {
      evt.preventDefault();
      evt.stopImmediatePropagation();
      evt.currentTarget.value = '';

      dispatch(actions.toggledChooseEngine(true));

      return;
    }

    dispatch(updatedInput(value, evt.inputType));
  };

export const searchSubmittedFinal =
  (event: SubmitEvent, suggestion?: Suggestion, provided?: string): Thunk =>
  (dispatch, getState) => {
    const state: GlobalState = getState();

    const term = provided || getTerm(suggestion) || state.search.provided;

    event?.preventDefault?.();
    const engine = selectEngine(state);

    if (suggestion?.type === 'openTab' && process.env.APP_PLATFORM !== 'web') {
      sendMessage({ type: 'switchTo', tabId: suggestion.id });
      return;
    }

    const choosenSearchTag = selectChoosenSearchTag(state);

    const href = (() => {
      if (suggestion) return suggestion.url;

      if (checkIsUrl(term)) return withHttp(term);

      if (choosenSearchTag) {
        return choosenSearchTag.u.replace('{{{s}}}', encodeURIComponent(term));
      }

      return createOrganicUrl({ term }, engine);
    })();

    const { dailyAdClicksCount } = state.search;

    const [gain, gainType] = ((): [number, string] => {
      if (suggestion?.type === 'ad') {
        return [dailyAdClicksCount < 5 ? getRandomInt(30, 80) : 0, 'ad'];
      }

      if (href.match(ENGINES.oh.url)) {
        return [20, 'oh'];
      }

      return [10, 'various'];
    })();

    if (gainType !== 'oh') {
      dispatch(incrementShells(gain));
    }

    dispatch(
      actions.searchSubmitted({
        gain,
        term,
        isAd: gainType === 'ad',
        searchTag: choosenSearchTag,
        hintId: selectActiveHintId(state),
      })
    );
    trackSubmit(
      event,
      suggestion,
      engine,
      gain,
      gainType,
      state.search.instantResults.counter,
      choosenSearchTag
    );

    window.stop();
    setTimeout(() => {
      window.location.href = href;
    }, 10);
  };

