const trackSearchTagSelect = (
  eventType: 'keydown' | 'click',
  searchTag: SearchTag,
  state: GlobalState
) => {
  if (!searchTag) return;

  trackAmplitudeEvent('Selected search tag', {
    category: 'Search',
    search_tag: searchTag.s,
    count: selectRendered(state)?.length || 0,
    event_type: eventType,
  });
};

const navigateNextSearchTag = (): Thunk => (dispatch, getState) => {
  const state = getState();
  const displayedSearchTags = selectDisplayedSearchTags(state);
  const choosen = selectChoosenSearchTag(state);

  const index = displayedSearchTags.findIndex(
    (searchTag) => searchTag.u === choosen?.u
  );
  const nextChoosen =
    index !== -1 ? displayedSearchTags[index + 1] : displayedSearchTags[0];
  dispatch(searchTagSelect(nextChoosen?.u || null));
};

const suggestionNavigate =
  (key: 'ArrowUp' | 'ArrowDown') => (dispatch, getState) => {
    let newIndex;
    const state = getState() as GlobalState;
    const { highlighted } = state.search;
    const list = selectSuggestions(state).filter(
      ({ type }) => type !== 'placeholder'
    );

    console.log('list', list);

    if (highlighted.id) {
      const index = list.findIndex(({ id }) => id === highlighted.id);
      newIndex = index + (key === 'ArrowUp' ? -1 : 1);
      if (newIndex < 0 || newIndex >= list.length) {
        newIndex = null;
      }
    } else {
      newIndex = key === 'ArrowUp' ? list.length - 1 : 0;
    }

    const newSuggestion = list[newIndex];
    dispatch(
      actions.suggestionNavigate({
        id: newSuggestion?.id,
        inputType: 'keyboard',
      })
    );
  };

export const keyDown =
  (event: KeyboardEvent): Thunk =>
  (dispatch, getState) => {
    const { key } = event;

    if (
      !['ArrowUp', 'ArrowDown', 'Enter', 'Escape', 'Tab', 'Backspace'].includes(
        key
      )
    )
      return;

    if (key === 'Backspace') {
      if ((event.target as HTMLInputElement).value) return;
      setTimeout(() => {
        dispatch(actions.pressedEscape(true));
      }, 1);

      return;
    }

    event.preventDefault();

    if (key === 'Enter') {
      const state = getState();
      dispatch(searchSubmitted(event, selectHighlighted(state)));
      return;
    }

    if (key === 'Escape') {
      dispatch(actions.pressedEscape(false));
      return;
    }

    if (key === 'ArrowUp' || key === 'ArrowDown') {
      dispatch(suggestionNavigate(key));
      return;
    }

    if (key === 'Tab') {
      dispatch(navigateNextSearchTag());
    }
  };

