export const speechEnded =
  (content: string) =>
  (dispatch): void => {
    dispatch(
      content
        ? searchSubmitted({ type: 'speech' }, null, content)
        : actions.speechEnded()
    );
  };

export const removeSuggestion =
  (s: Suggestion): Thunk =>
  async (dispatch, getState) => {
    const state = getState();

    const history = state.search.history.filter((term) => term !== s.term);

    dispatch(actions.removeSuggestion(history));
  };

export const searchTagSelect =
  (u: string, eventType: 'click' | 'keydown' = 'click'): Thunk =>
  (dispatch, getState) => {
    dispatch(actions.searchTagSelected(u));
    const state = getState();
    const searchTag = selectChoosenSearchTag(state);
    if (searchTag) {
      trackSearchTagSelect(eventType, searchTag, state);
    }

    const term = state.search.provided;

    if (term) {
      dispatch(fetchSuggestions({ term, inputType: 'searchTag' }));
    }
  };
